// Money is a type, but it is imported as a value.
import { Money } from './money.ts';
export function total(items: Money[]): number {
  return items.reduce((sum, m) => sum + m.amount, 0);
}

import { total } from '../src/app.ts';
const n: number = total([{ amount: 10, currency: 'USD' }]);
export { n };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total } from '../src/app.ts';
test('total', () => assert.equal(total([{ amount: 10, currency: 'USD' }, { amount: 5, currency: 'USD' }]), 15));

