// Nothing is exported yet — the consumer cannot import Lab or makeLab.
type Lab = { code: string; seats: number };
function makeLab(code: string, seats: number): Lab {
  return { code, seats };
}

import { makeLab } from '../src/lab.ts';
import type { Lab } from '../src/lab.ts';
const be: Lab = makeLab('BE-201', 40);
export { be };

import type { Lab } from '../src/lab.ts';
const bad: Lab = { code: 'BE-201', seats: 'forty' }; // expect TS2322
export { bad };

